/* ==========================================================================
   Touris 知途 · 景点经纬度（WGS-84）

   为什么单独一个文件：
     city-data.js 里北京/上海/威海由 makeCity() 从配置对象产出，京都保留在 data.js，
     杭州/广州的坐标由 city-hangzhou-guangzhou.js 从 CITY_EXPANSION 取。四处格式各异。
     本文件在最后统一给缺坐标的城市补上，不动上述任一文件的既有结构。

   覆盖范围：
     京都 27 · 北京 21 · 上海 21（此前三城没有坐标，真实地图接不上，回退成示意图）
     威海 17（该城原本 geo 完全为空）
     杭州/广州在 city-expansion.js 已有完整坐标，这里不重复。

   坐标口径：
     - 区域/街道类（先斗町、西阵、三里屯、武康路…）取代表中心，不取某个门牌
     - 公园类取 OSM 公园多边形质心，故 颐和园/北海公园 会落在水面上；要"落脚点"请改用大门
     - 威海点位跨度很大：刘公岛为近海岛屿，成山头/那香海/海驴岛/鸡鸣岛/荣成海草房
       均在荣成或海上，离市区 30–65 km，不是市区内散点
     - 经 OSM(Nominatim/Overpass) 与 Wikidata P625 交叉核对，非凭记忆填写

   未收录：威海「猫头山」—— OSM 与维基均无对应条目，查不到就不写，
   地图上少一个点，好过打错位置。

   与既有 geo 的字段对齐：按城市可整体覆盖 source，个别点位可单独标注。
   ========================================================================== */
(function () {
  'use strict';

  const SRC_OSM = 'https://www.openstreetmap.org/';
  const SRC_WIKI = 'https://zh.wikipedia.org/wiki/';
  const NOTE = '景点参考位置，非入口导航';

  /* 写法一：[纬度, 经度]  —— 写成直观顺序，输出时转成 {lat,lng}
     写法二：{ ll:[纬度,经度], src:'…' } —— 个别点位需要单独标注来源时用 */
  const DATA = {
    '京都': {
      '京都站':           [34.9855, 135.7578],
      '清水寺':           [34.9946, 135.7848],
      '二年坂三年坂':     [34.9983, 135.7800],
      '祇园花见小路':     [35.0027, 135.7749],
      '八坂神社':         [35.0036, 135.7783],
      '伏见稻荷大社':     [34.9671, 135.7732],
      '金阁寺':           [35.0395, 135.7295],
      '龙安寺':           [35.0345, 135.7183],
      '岚山竹林':         [35.0167, 135.6711],
      '天龙寺':           [35.0161, 135.6734],
      '渡月桥':           [35.0129, 135.6778],
      '锦市场':           [35.0050, 135.7653],
      '二条城':           [35.0140, 135.7485],
      '银阁寺':           [35.0269, 135.7984],
      '哲学之道':         [35.0215, 135.7952],
      '京都国立博物馆':   [34.9899, 135.7729],
      '三十三间堂':       [34.9882, 135.7718],
      '平安神宫':         [35.0161, 135.7829],
      '河原町':           [35.0038, 135.7693],
      '先斗町':           [35.0061, 135.7711],
      '鸭川河畔':         [35.0038, 135.7715],
      '西阵':             [35.0297, 135.7519],
      '京都塔':           [34.9875, 135.7594],
      '东寺':             [34.9806, 135.7477],
      '南禅寺':           [35.0111, 135.7942],
      '出町柳桝形商店街': [35.0303, 135.7689],
      '嵯峨野':           [35.0183, 135.6729]
    },
    '北京': {
      '故宫博物院':   [39.9174, 116.3908],
      '景山公园':     [39.9245, 116.3904],
      '天安门广场':   [39.9028, 116.3915],
      '天坛公园':     [39.8799, 116.4029],
      '颐和园':       [39.9901, 116.2647],
      '圆明园':       [40.0050, 116.2948],
      '慕田峪长城':   [40.4380, 116.5619],
      '什刹海':       [39.9380, 116.3871],
      '南锣鼓巷':     [39.9358, 116.3969],
      '雍和宫':       [39.9456, 116.4110],
      '国子监':       [39.9459, 116.4070],
      '798艺术区':    [39.9828, 116.4905],
      '三里屯':       [39.9361, 116.4488],
      '前门大街':     [39.8879, 116.3920],
      '大栅栏':       [39.8945, 116.3902],
      '国家博物馆':   [39.9037, 116.3954],
      '北海公园':     [39.9264, 116.3825],
      '亮马河':       [39.9471, 116.4609],
      '鼓楼':         [39.9393, 116.3897],
      '牛街':         [39.8849, 116.3575],
      '北京南站':     [39.8637, 116.3728]
    },
    '上海': {
      '外滩':         [31.2390, 121.4863],
      '南京东路':     [31.2377, 121.4753],
      '豫园':         [31.2289, 121.4880],
      '城隍庙':       [31.2279, 121.4882],
      '陆家嘴':       [31.2399, 121.5036],
      '上海博物馆':   [31.2302, 121.4710],
      '上海中心':     [31.2356, 121.5013],
      '武康路':       [31.2105, 121.4349],
      '安福路':       [31.2161, 121.4397],
      '思南公馆':     [31.2161, 121.4644],
      '田子坊':       [31.2103, 121.4641],
      '新天地':       [31.2219, 121.4704],
      '愚园路':       [31.2239, 121.4292],
      '静安寺':       [31.2252, 121.4408],
      '苏州河':       [31.2453, 121.4857],
      '朱家角古镇':   [31.1125, 121.0497],
      '中华艺术宫':   [31.1865, 121.4899],
      '徐汇滨江':     [31.1754, 121.4586],
      '龙华寺':       [31.1768, 121.4473],
      '上海南站':     [31.1550, 121.4260],
      '虹口北外滩':   [31.2540, 121.4948]
    },
    /* 威海：跨度极大，市区/近海岛屿/荣成海岸三处相距数十公里。
       「猫头山」查无对应条目，未收录。 */
    '威海': {
      '刘公岛':           [37.5057, 122.1834],
      '中国甲午战争博物院': { ll: [37.5007, 122.1764], src: SRC_WIKI + '%E4%B8%AD%E5%9B%BD%E7%94%B2%E5%8D%88%E6%88%98%E4%BA%89%E5%8D%9A%E7%89%A9%E9%A6%86' },
      '定远舰景区':       [37.4983, 122.1846],
      '幸福门':           [37.5005, 122.1228],
      '威海公园':         [37.4615, 122.1406],
      '悦海公园':         [37.4508, 122.1542],
      '国际海水浴场':     [37.5287, 122.0417],
      '火炬八街':         [37.5218, 122.0264],
      '半月湾':           [37.5282, 122.1528],
      '成山头':           { ll: [37.3944, 122.6992], src: SRC_WIKI + '%E6%88%90%E5%B1%B1%E5%A4%B4' },
      '那香海':           [37.4016, 122.4031],
      '海驴岛':           [37.4464, 122.6662],
      '鸡鸣岛':           [37.4495, 122.4810],
      '荣成海草房':       [37.0408, 122.5588],
      '华夏城':           [37.4218, 122.1107],
      '威海站':           [37.4260, 122.1385],
      '环翠楼公园':       [37.5044, 122.1046]
    }
  };

  /* 转成既有 geo 的字段格式；兼容 [lat,lng] 与 {ll,src} 两种写法 */
  function toGeo(list) {
    const out = {};
    Object.keys(list).forEach(name => {
      const raw = list[name];
      const ll = Array.isArray(raw) ? raw : raw.ll;
      if (!Array.isArray(ll) || ll.length !== 2) return;   // 查不到的条目直接跳过
      out[name] = {
        lat: ll[0],
        lng: ll[1],
        source: (Array.isArray(raw) ? SRC_OSM : (raw.src || SRC_OSM)),
        coordinateSystem: 'WGS84',
        note: NOTE
      };
    });
    return out;
  }

  const GEO = {};
  Object.keys(DATA).forEach(city => { GEO[city] = toGeo(DATA[city]); });

  /* 挂到已建好的城市对象上；已有 geo 的城市（杭州/广州）不覆盖，
     但缺项会被补齐 —— 它们的坐标更全，这里只做加法。 */
  const target = (typeof globalThis !== 'undefined' && globalThis.CITY_DATA) || null;

  /* 京都是特例：它不在 CITY_DATA 里，app.js 的 city() 对它返回 null，
     于是回退到 data.js 的顶层常量（POI/SPOTS/DINING）。这里把它补成一个
     正式城市对象，好让路线计算与真实地图走和北京/上海同一条路。 */
  if (target && !target['京都'] && typeof POI !== 'undefined') {
    target['京都'] = { name: '京都', poi: POI };
  }

  /* 威海点位跨度 30–65 km（市区 / 近海岛屿 / 荣成海岸），按平均质心算出的
     center 会落在海上，所以显式给市区中心；真正的视野由 fitBounds 决定。 */
  if (target && target['威海']) {
    target['威海'].center = [37.5044, 122.1046];   // 环翠楼（市区）
  }

  if (target) {
    Object.keys(GEO).forEach(city => {
      const c = target[city];
      if (!c) return;
      c.geo = Object.assign({}, GEO[city], c.geo || {});  // 既有值优先
      if (!c.center) {
        const pts = Object.keys(c.geo).map(n => c.geo[n]);
        if (pts.length) {
          c.center = [
            pts.reduce((a, p) => a + p.lat, 0) / pts.length,
            pts.reduce((a, p) => a + p.lng, 0) / pts.length
          ];
        }
      }
    });
  }

  /* 暴露出来便于校验脚本直接比对本表与各城市实际生效的 geo */
  globalThis.TOURIS_GEO = GEO;
})();
